from lib import *
S = SS('f189')
R = J('f189'); C = R['cases']; K = R['kill']
steps = [
    step(f"docker stop 先给容器的 1 号进程发 SIGTERM。这里用「被发信号的进程」代替 1 号进程(本机不是 Linux 容器),3 秒的请求进行中给它发 SIGTERM:直接运行 gunicorn(exec 形式)→ 被发信号的就是 gunicorn,{C[0]['pid1_exit']} s 后退出,请求 {C[0]['req']};入口脚本最后写 exec gunicorn → 同样({C[4]['pid1_exit']} s);入口脚本最后一行只写 gunicorn(没有 exec)→ 被发信号的是 sh,不是 gunicorn(同一个 pid:{C[3]['same_pid']}),sh 立刻({C[3]['pid1_exit']} s)被 SIGTERM 终止,gunicorn 没有收到信号、继续运行(孤儿:{C[3]['orphan']})。脚本里不加 exec,信号就停在 sh 这一层。", t=tl(S(1)), done=lidx(S(1), 'exec 形式', '最后一行是 exec'), mark=lidx(S(1), '没有 exec', '多条命令'), kv=KV([['exec gunicorn', 'gunicorn 直接收到 SIGTERM'], ['不加 exec 的脚本', 'sh 被终止,gunicorn 成孤儿']], ['不加 exec 的脚本'])),
    step(f"shell 形式 CMD gunicorn ... 要看 sh 怎么处理:本机的 /bin/sh(bash 3.2,POSIX 模式)对单条命令 sh -c \"gunicorn ...\" 会直接 exec,被发信号的就是 gunicorn({C[1]['same_pid']}),行为和 exec 形式一样({C[1]['pid1_exit']} s 退出);但命令后面再加一条(sh -c \"gunicorn ...; echo done\"),sh 留在前面当父进程,收到 SIGTERM 立即退出({C[2]['pid1_exit']} s),gunicorn 变成孤儿继续运行(再跑一次同样如此:{R['again']['orphan']})。注意这是本机 sh 的行为:容器镜像里的 sh(Debian 的 dash、Alpine 的 busybox ash)是否对单条命令 exec,本篇没有验证——不要依赖它,用 exec 形式。容器里 1 号进程退出后内核会终止剩余进程,这里没有 Linux 容器,没有验证。", t=tl(S(2)), done=lidx(S(2), '再跑一次'), mark=[], kv=KV([['sh -c 单条命令(本机)', '直接 exec'], ['sh -c 多条命令', 'sh 不转发信号']], ['sh -c 多条命令'])),
    step(f"grace 期比请求短时:docker stop 默认等 10 秒再补 SIGKILL。这里用「SIGTERM 之后 1.5 秒补 SIGKILL」代替(给整个进程组发),3 秒的请求 → {K['r']},{K['t']} s 后被断开。优雅关闭要多久(--graceful-timeout、请求最长耗时,见第 180 篇)必须小于容器的停止宽限期(docker stop -t、Kubernetes 的 terminationGracePeriodSeconds),否则进行中的请求仍会被杀。", t=tl(S(3)), done=[], mark=lidx(S(3), 'SIGTERM 之后'), kv=KV([['SIGTERM + 1.5 s 后 SIGKILL', f"请求 {K['r']}"], ['要求', 'graceful 时间 < 宽限期']], ['要求'])),
]
A = mkartf('f189', 189, 'Flask,Docker,信号,gunicorn,exec,真实验证,动画演示',
    f'用真实进程验证容器里的信号传递问题:SIGTERM 发给 sh 而不是 gunicorn 时(入口脚本没写 exec、sh -c 后面还有别的命令),gunicorn 没有收到信号并成为孤儿;exec gunicorn 与直接运行时 gunicorn 直接收到信号并在 {C[0]["pid1_exit"]} s 内优雅退出;宽限期比请求短时请求被 SIGKILL 打断。没有在 Docker 容器里验证。',
    '容器停止时 docker stop 发的是 SIGTERM,但收到它的是 1 号进程。如果 1 号进程是 sh 而不是 gunicorn,优雅关闭就根本没有机会发生。这篇用本机的真实进程模拟这件事:被发信号的进程分别是 gunicorn 本身还是外面包着的 sh。需要说明:没有真正的 Docker 容器(拉不到基础镜像),也不是 Linux,所以 1 号进程的特殊信号语义没有验证(Dockerfile 的写法见第 178 篇,优雅关闭见第 180 篇)。',
    [('exec', '入口脚本里加 exec 让 gunicorn 接替 sh 成为被发信号的进程'), ('孤儿', 'sh 被 SIGTERM 终止而 gunicorn 没收到信号继续运行'), ('宽限期', '优雅关闭时间必须小于容器的停止宽限期')],
    [('谁收到 SIGTERM', '<p>上一篇:<a href="flask-db-connection-health-check.html">数据库连接健康检查</a>;下一篇:<a href="flask-startup-time.html">Flask 应用启动耗时</a>。</p><p>实验在 macOS 上用 <code>/bin/sh</code>(bash 3.2)与真实的 gunicorn 进程完成,没有使用 Docker。</p>'), ('shell 形式', None), ('SIGKILL 补刀', None)],
    steps, [ENV_F + '。macOS /bin/sh(bash 3.2.57)、gunicorn、真实进程(不是 Docker 容器)', '没有验证:Linux 容器里 1 号进程不套用默认信号处理(没装 handler 的进程会忽略 SIGTERM)、dash/busybox ash 对 sh -c 单条命令是否 exec、tini 与 docker run --init、僵尸进程回收、docker stop 的 10 秒默认值与 Kubernetes terminationGracePeriodSeconds 的实际行为(只用 SIGKILL 延时做了模拟)'], '容器信号处理')
